-- MagicLink.NET PostgreSQL store, version 1: OpenIddict's applications, authorizations, scopes and tokens.
-- Ids are generated by the store. Every update writes a new concurrency_token and only succeeds when
-- the row still holds the token the caller read.

CREATE SCHEMA IF NOT EXISTS magiclink;

CREATE TABLE magiclink.applications (
    id                        uuid PRIMARY KEY,
    concurrency_token         text NOT NULL,
    application_type          text NULL,
    client_id                 text NULL,
    client_secret             text NULL,
    client_type               text NULL,
    consent_type              text NULL,
    display_name              text NULL,
    display_names             jsonb NULL,
    json_web_key_set          jsonb NULL,
    permissions               text[] NOT NULL DEFAULT '{}',
    post_logout_redirect_uris text[] NOT NULL DEFAULT '{}',
    redirect_uris             text[] NOT NULL DEFAULT '{}',
    requirements              text[] NOT NULL DEFAULT '{}',
    settings                  jsonb NULL,
    properties                jsonb NULL,
    CONSTRAINT uq_applications_client_id UNIQUE (client_id)
);

CREATE INDEX ix_applications_redirect_uris ON magiclink.applications USING gin (redirect_uris);
CREATE INDEX ix_applications_post_logout_redirect_uris ON magiclink.applications USING gin (post_logout_redirect_uris);

CREATE TABLE magiclink.authorizations (
    id                uuid PRIMARY KEY,
    concurrency_token text NOT NULL,
    application_id    uuid NULL REFERENCES magiclink.applications (id) ON DELETE CASCADE,
    creation_date     timestamptz NULL,
    properties        jsonb NULL,
    scopes            text[] NOT NULL DEFAULT '{}',
    status            text NULL,
    subject           text NULL,
    type              text NULL
);

CREATE INDEX ix_authorizations_application_subject_status_type ON magiclink.authorizations (application_id, subject, status, type);
CREATE INDEX ix_authorizations_subject ON magiclink.authorizations (subject);

CREATE TABLE magiclink.scopes (
    id                uuid PRIMARY KEY,
    concurrency_token text NOT NULL,
    name              text NULL,
    description       text NULL,
    descriptions      jsonb NULL,
    display_name      text NULL,
    display_names     jsonb NULL,
    resources         text[] NOT NULL DEFAULT '{}',
    properties        jsonb NULL,
    CONSTRAINT uq_scopes_name UNIQUE (name)
);

CREATE INDEX ix_scopes_resources ON magiclink.scopes USING gin (resources);

CREATE TABLE magiclink.tokens (
    id                uuid PRIMARY KEY,
    concurrency_token text NOT NULL,
    application_id    uuid NULL REFERENCES magiclink.applications (id) ON DELETE CASCADE,
    authorization_id  uuid NULL REFERENCES magiclink.authorizations (id) ON DELETE CASCADE,
    creation_date     timestamptz NULL,
    expiration_date   timestamptz NULL,
    redemption_date   timestamptz NULL,
    payload           text NULL,
    properties        jsonb NULL,
    reference_id      text NULL,
    status            text NULL,
    subject           text NULL,
    type              text NULL,
    CONSTRAINT uq_tokens_reference_id UNIQUE (reference_id)
);

CREATE INDEX ix_tokens_application_subject_status_type ON magiclink.tokens (application_id, subject, status, type);
CREATE INDEX ix_tokens_authorization_id ON magiclink.tokens (authorization_id);
CREATE INDEX ix_tokens_subject ON magiclink.tokens (subject);
CREATE INDEX ix_tokens_expiration_date ON magiclink.tokens (expiration_date);
